// Upload a patient document (PDF/JPEG/PNG)  (permissions: patient.document.upload)
export const uploadDocumentPatientsDocuments = (patient_id, body) =>
  api("POST", `/patients/${patient_id}/documents`, body, { idempotent: true });   // api(): see get_guide('envelope-and-errors')

// List patient documents  (permissions: patient.document.view)
export const listDocumentsPatients = (patient_id) =>
  api("GET", `/patients/${patient_id}/documents`, undefined);   // api(): see get_guide('envelope-and-errors')

// Download a patient document  (permissions: patient.document.view)
export const downloadDocumentPatientDocuments = (document_id) =>
  api("GET", `/patient-documents/${document_id}/download`, undefined);   // api(): see get_guide('envelope-and-errors')

// Clear a discharge stage (in order)  (permissions: any logged-in user)
export const clearStage = (admission_id, stage, body) =>
  api("POST", `/admissions/${admission_id}/discharge/${stage}/clear`, body);   // api(): see get_guide('envelope-and-errors')

// Finalize the running IPD bill (then collect payment)  (permissions: ipd.discharge.clear_billing)
export const finalBill = (admission_id, body) =>
  api("POST", `/admissions/${admission_id}/final-bill`, body);   // api(): see get_guide('envelope-and-errors')

// Admissions (default: all live ones; admissions desk queue)  (permissions: ipd.admission.view)
export const listAdmissions = () =>
  api("GET", `/admissions`, undefined);   // api(): see get_guide('envelope-and-errors')

// Admissions desk: Allocate Bed  (permissions: ipd.admission.allocate)
export const allocate = (admission_id, body) =>
  api("POST", `/admissions/${admission_id}/allocate-bed`, body);   // api(): see get_guide('envelope-and-errors')

// Admissions manager: cross-ward overflow bed  (permissions: ipd.admission.overflow)
export const overflow = (admission_id, body) =>
  api("POST", `/admissions/${admission_id}/overflow-override`, body);   // api(): see get_guide('envelope-and-errors')

// No bed: add to the ward waitlist  (permissions: ipd.waitlist.manage, ipd.admission.request)
export const waitlist = (admission_id, body) =>
  api("POST", `/admissions/${admission_id}/waitlist`, body);   // api(): see get_guide('envelope-and-errors')

// Ward waitlist  (permissions: ipd.admission.view)
export const wardWaitlist = (ward_id) =>
  api("GET", `/wards/${ward_id}/waitlist`, undefined);   // api(): see get_guide('envelope-and-errors')

// Patient arrived at the bed (Admitted, bed Occupied)  (permissions: ipd.admission.allocate, ipd.flowsheet.record)
export const admit = (admission_id, body) =>
  api("POST", `/admissions/${admission_id}/admit`, body, { idempotent: true });   // api(): see get_guide('envelope-and-errors')

// Cancel an admission that will not happen (before the patient is admitted)  (permissions: ipd.admission.allocate, ipd.admission.request)
export const cancelAdmission = (admission_id, body) =>
  api("POST", `/admissions/${admission_id}/cancel`, body);   // api(): see get_guide('envelope-and-errors')

// Confirm how a Code Red admission is paid (ends its billing deferral)  (permissions: ipd.admission.allocate, ipd.discharge.clear_billing)
export const confirmBilling = (admission_id, body) =>
  api("POST", `/admissions/${admission_id}/confirm-billing`, body);   // api(): see get_guide('envelope-and-errors')
